$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$taken = @{}; $tt.specific.PSObject.Properties | ? { $mine -notcontains $_.Name } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  $had = @($tt.subjects.$c | ? { $_ }); "  " + $c + " already has " + $had.Count + " sets - the new ones are ADDED, nothing removed"
  foreach ($k in $kinds) { if ($had -contains $k) { "  SET NAME ALREADY IN THIS CATEGORY: " + $k; $clash = $true } }
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = @($had + $kinds) } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $kinds }
  foreach ($k in $kinds) {
    $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $final[$o] = $nn; $nn })
    if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.$k = $names } else { $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($clash -or $afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
"  saving the split-card settings and the tattoo descriptions..."
$n = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  RUN ("SETKV render:" + $ks + " The tattoo in both panels is identical.") | Out-Null
  RUN ("SETKV shape:" + $ks + " 3:2") | Out-Null
  RUN ("SETKV split:" + $ks + " yes") | Out-Null
  foreach ($o in $cats[$c][$k]) { RUN ("SETKV build:" + (& $slug $final[$o]) + " " + $b[$o]) | Out-Null; $n++ }
} }
"  " + $n + " descriptions saved - waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
$got2 = Read-Tree
$short = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) { $h = @($got2.tree.specific.$k | ? { $_ }).Count; if ($h -ne $cats[$c][$k].Count) { "  STILL SHORT: " + $k + " has " + $h; $short++ } } }
if ($short) { "== " + $short + " sets short - send me this output ==" } else {
"== Heavy Blackwork saved - the test cards: =="
"== looking for old style words on Heavy Blackwork and its sets (exact names) =="
$want = @('context:heavy-blackwork-animals-built-from-black','context:heavy-blackwork-black-and-skin','context:heavy-blackwork-black-architecture','context:heavy-blackwork-black-body-flow','context:heavy-blackwork-dark-nature','context:heavy-blackwork-heavy-abstract','context:heavy-blackwork-illustrative-heavy-blackwork','context:heavy-blackwork-monsters-and-dark-creatures','context:heavy-blackwork-primal-and-ancient','context:heavy-blackwork-push-heavy-blackwork')
$tmp = Join-Path $env:TEMP "aura-ctx-heavy-blackwork.json"
ConvertTo-Json @($want) | Set-Content -Path $tmp -Encoding utf8
$out = (npx wrangler kv bulk get $tmp --namespace-id $ns --remote 2>$null | Out-String)
$hits = [regex]::Matches($out, '"(context:[^"]+)":\s*"((?:[^"\\]|\\.)*)"')
if ($hits.Count -eq 0) { "  none found" } else { foreach ($h in $hits) { "  removed " + $h.Groups[1].Value + ": " + $h.Groups[2].Value; npx wrangler kv key delete --namespace-id $ns $h.Groups[1].Value --remote 2>$null | Out-Null }; "  waiting 70 seconds"; Start-Sleep -Seconds 70 }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
}
